import { useState } from "react";
import { useNavigate } from "react-router-dom";
import styled from "styled-components";
import { authenticate, getStoredPassword, DOCTOR_EMAIL } from "../../../utils/cookies";
import Button from "../../../components/ui/Button";
import Card from "../../../components/ui/Card";
import Input from "../../../components/ui/Input";

const Page = styled.main`
  min-height: 100vh;
  display: grid;
  grid-template-columns: minmax(320px, 0.95fr) minmax(360px, 1.05fr);
  background: #eef2ff;

  @media (max-width: 840px) {
    grid-template-columns: 1fr;
  }
`;

const BrandPanel = styled.aside`
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 44px;
  background: linear-gradient(180deg, #5b21b6 0%, #4338ca 100%);
  color: #fff;

  @media (max-width: 840px) {
    padding: 28px;
  }
`;

const BrandTitle = styled.h1`
  margin: 0;
  font-size: 42px;
  line-height: 1.05;
  font-weight: 900;
`;

const BrandText = styled.p`
  max-width: 420px;
  margin-top: 20px;
  font-size: 16px;
  line-height: 1.9;
  color: rgba(255, 255, 255, 0.85);
`;

const LoginCard = styled.section`
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 42px 24px;
  min-height: 100vh;
  background: #f8fafc;
`;

const Title = styled.h2`
  margin: 0;
  color: #111827;
  font-size: 30px;
  font-weight: 800;
`;

const Subtitle = styled.p`
  margin: 12px 0 28px;
  color: #6b7280;
  line-height: 1.7;
`;

const Form = styled.form`
  display: grid;
  gap: 18px;
`;

const Field = styled.label`
  display: grid;
  gap: 8px;
  font-size: 14px;
  color: #334155;
  font-weight: 700;
`;

const Hint = styled.div`
  margin-top: 10px;
  font-size: 13px;
  color: #64748b;
  line-height: 1.7;
`;

const Footer = styled.div`
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
`;

const Message = styled.p<{ error?: boolean }>`
  margin: 0;
  color: ${({ error }) => (error ? "#dc2626" : "#16a34a")};
  font-size: 14px;
  line-height: 1.6;
`;

const SmallAction = styled.button`
  border: none;
  background: transparent;
  color: #7c3aed;
  font-size: 14px;
  font-weight: 700;
  cursor: pointer;
  text-align: left;
  padding: 0;
`;

const Login = () => {
  const navigate = useNavigate();
  const [email, setEmail] = useState(DOCTOR_EMAIL);
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  const storedPassword = getStoredPassword();

  const handleLogin = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setError("");
    setSuccess("");

    if (email.trim().toLowerCase() !== DOCTOR_EMAIL) {
      setError("Please use your assigned doctor email.");
      return;
    }

    if (password !== storedPassword) {
      setError("Invalid password. Contact admin or reset your password.");
      return;
    }

    authenticate(email.trim().toLowerCase());
    navigate("/dashboard");
  };

  return (
    <Page>
      <BrandPanel>
        <BrandTitle>Doctor Panel</BrandTitle>
        <BrandText>
          Access your clinic dashboard, manage appointments, and update your profile settings from one clean interface.
        </BrandText>
      </BrandPanel>

      <LoginCard>
        <Card>
          <Title>Doctor Login</Title>
          <Subtitle>
            Sign in with your assigned doctor credentials. The first-time password is <strong>12345</strong>.
          </Subtitle>
          <Form onSubmit={handleLogin}>
            <Field>
              Email address
              <Input
                type="email"
                value={email}
                onChange={(event) => setEmail(event.target.value)}
                required
              />
            </Field>
            <Field>
              Password
              <Input
                type="password"
                value={password}
                onChange={(event) => setPassword(event.target.value)}
                required
              />
            </Field>
            {error && <Message error>{error}</Message>}
            {success && <Message>{success}</Message>}
            <Button type="submit">Sign in</Button>
            <Footer>
              <SmallAction type="button" onClick={() => navigate("/reset-password")}>
                Forgot password?
              </SmallAction>
              <Hint>Admin-created accounts only. Signup is disabled.</Hint>
            </Footer>
          </Form>
        </Card>
      </LoginCard>
    </Page>
  );
};

export default Login;
